package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

var WsEofFlag string // PIC X len=1 = "N"
var WsDiscount decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string // PIC ZZ,ZZ9.99 len=9
var WsNetEd string // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var discRec DiscRec
var discFile *os.File
var discReader *bufio.Reader
var atEnd bool

func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// v is already truncated/rounded to scale.
	// Keep low-order digits that fit.
	capacity := int64(math.Pow10(intDigits + int(scale)))
	// Use Shift to get scaled integer
	scaled := v.Shift(scale)
	// IntPart may truncate toward zero; v already has correct scale, so it's integer.
	scaledInt := scaled.IntPart()
	// modulo to keep low-order digits
	// For positive numbers modulus is enough; for negative preserve sign
	if scaledInt >= capacity || scaledInt <= -capacity {
		// Go % keeps sign of dividend
		scaledInt = scaledInt % capacity
	}
	return decimal.New(scaledInt, -scale)
}

func truncateStore(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	return storeDecimal(t, intDigits, scale)
}

func roundStore(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	r := v.Round(scale)
	return storeDecimal(r, intDigits, scale)
}

func formatEdited(v decimal.Decimal, pic string) string {
	n := len(pic)
	// find dot position
	dotPos := strings.Index(pic, ".")
	var fracDigits int
	var intPicEnd int // index of dot or n
	if dotPos >= 0 {
		intPicEnd = dotPos
		// count '9'/'Z' after dot
		for i := dotPos + 1; i < n; i++ {
			if pic[i] == '9' || pic[i] == 'Z' {
				fracDigits++
			}
		}
	} else {
		intPicEnd = n
		fracDigits = 0
	}
	// count integer digit positions
	intDigits := 0
	for i := 0; i < intPicEnd; i++ {
		if pic[i] == '9' || pic[i] == 'Z' {
			intDigits++
		}
	}

	// absolute value truncated to fracDigits (should already be)
	absVal := v.Abs().Truncate(int32(fracDigits))

	// integer part and fractional part
	intPart := absVal.Truncate(0).IntPart()
	// keep low-order digits if overflow (MOVE high-order truncation)
	if intDigits > 0 {
		capInt := int64(math.Pow10(intDigits))
		if intPart >= capInt {
			intPart = intPart % capInt
		}
	}
	// fractional digits
	var fracPart int64
	if fracDigits > 0 {
		// fractional = (absVal - intPart) * 10^fracDigits truncated
		fracDecimal := absVal.Sub(decimal.New(intPart, 0)).Shift(int32(fracDigits)).Truncate(0)
		fracPart = fracDecimal.IntPart()
		if fracPart < 0 {
			fracPart = -fracPart
		}
	}

	// Build integer digit array of length intDigits padded with leading zeros
	intDigitsArr := make([]byte, intDigits)
	tmp := intPart
	for i := intDigits - 1; i >= 0; i-- {
		intDigitsArr[i] = byte('0' + (tmp % 10))
		tmp /= 10
	}

	// Prepare output chars, fill picture literals
	out := make([]byte, n)
	// Fill integer part placeholders with digits
	idx := 0 // index in intDigitsArr
	for i := 0; i < n; i++ {
		c := pic[i]
		switch c {
		case 'Z', '9':
			if i < intPicEnd {
				// integer placeholder
				out[i] = intDigitsArr[idx]
				idx++
			} else {
				// fractional placeholder
				// will fill later
			}
		case ',':
			out[i] = ','
		case '.':
			out[i] = '.'
		default:
			out[i] = c
		}
	}
	// fill fractional placeholders
	if fracDigits > 0 {
		// extract frac digits string padded
		fracStr := fmt.Sprintf("%0*d", fracDigits, fracPart)
		fIdx := 0
		for i := intPicEnd + 1; i < n; i++ {
			if pic[i] == '9' || pic[i] == 'Z' {
				out[i] = fracStr[fIdx]
				fIdx++
			} else {
				// shouldn't happen
				out[i] = pic[i]
			}
		}
	}

	// Apply Z suppression for integer part
	seenNonZero := false
	for i := 0; i < intPicEnd; i++ {
		pc := pic[i]
		if pc == ',' {
			if !seenNonZero {
				out[i] = ' '
			} else {
				out[i] = ','
			}
			continue
		}
		if pc == 'Z' || pc == '9' {
			digit := out[i]
			if !seenNonZero {
				if pc == '9' {
					// 9 always prints, ends suppression
					seenNonZero = true
					// digit stays (could be '0')
				} else { // Z
					if digit != '0' {
						seenNonZero = true
						// keep digit
					} else {
						out[i] = ' '
						// still suppressed
					}
				}
			} else {
				// already seen, keep digit
			}
		}
	}
	// Negative sign handling: not needed for this program, but if negative we would
	// need to place '-' at leftmost suppressed position. Omit.

	return string(out)
}

func formatPZZZZ9_99(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZ9.99")
}
func formatPZZZZZZZ9_99(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZZ,ZZ9.99")
}

func parsePrice(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, -2)
	}
	// s should be digits only
	// remove any non-digit (should not happen)
	filtered := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			filtered += string(ch)
		}
	}
	if filtered == "" {
		return decimal.New(0, -2)
	}
	n, _ := strconv.ParseInt(filtered, 10, 64)
	return decimal.New(n, -2)
}
func parsePct(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	filtered := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			filtered += string(ch)
		}
	}
	if filtered == "" {
		return 0
	}
	n, _ := strconv.ParseInt(filtered, 10, 64)
	return n
}

func readPara() {
	if atEnd {
		return
	}
	line, err := discReader.ReadString('\n')
	if err != nil {
		// EOF
		if len(line) == 0 {
			WsEofFlag = "Y"
			atEnd = true
			return
		}
		// last line without newline, treat as record
	}
	// strip trailing \n and \r
	line = strings.TrimRight(line, "\r\n")
	// pad with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	discRec.DrItem = line[0:6]
	discRec.DrPrice = parsePrice(line[6:13])
	discRec.DrPct = parsePct(line[13:15])
	if err != nil && len(line) == 0 {
		// already handled
	}
	// Check for EOF after reading? The next call will detect
	// If ReadString returned io.EOF we consumed last line; next call will get EOF with empty line
	// To know we are done, we need to peek: if err == io.EOF we still processed that line successfully
	// So we set flag only on next read where err==io.EOF and line empty
	if err != nil {
		// we have just read last line; next read will trigger EOF
		// But we need to remember that next read should set done
		// We can leave atEnd false now, but if io.EOF we can set a flag that next read is EOF
		// Simplest: if err != nil, after processing, set a one-line buffer exhausted marker
		// We'll handle by checking: if err != nil then next read should be EOF.
		// We achieve by setting discReader to return EOF next time; already will.
		// No action now.
	}
	// Actually need to detect EOF correctly: if err is io.EOF and line was empty already handled.
	// For non-empty last line, we should not set done yet.
	// So we keep a lookahead: try Peek
	// Use simpler approach: check if underlying read would hit EOF by peeking
	// We'll attempt to peek 1 byte; if error then next read will be EOF, but current is valid.
	// Don't set done now.
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func processPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	prod := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct))
	quot := prod.Shift(-2)
	WsDiscount = roundStore(quot, 5, 2)
	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	diff := discRec.DrPrice.Sub(WsDiscount)
	WsNet = truncateStore(diff, 5, 2)
	// ADD WS-NET TO WS-TOTAL-NET
	sum := WsTotalNet.Add(WsNet)
	WsTotalNet = truncateStore(sum, 8, 2)
	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	// overflow for 9(3)
	if WsCount > 999 {
		WsCount = WsCount % 1000
	}
	WsPriceEd = formatPZZZZ9_99(discRec.DrPrice)
	WsDiscEd = formatPZZZZ9_99(WsDiscount)
	WsNetEd = formatPZZZZ9_99(WsNet)
	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	// DR-PCT is PIC 9(2) zero-padded
	pctStr := fmt.Sprintf("%02d", discRec.DrPct)
	// DR-PCT can overflow 2 digits? Keep low-order 2 digits
	if discRec.DrPct > 99 || discRec.DrPct < 0 {
		mod := discRec.DrPct % 100
		if mod < 0 {
			mod = -mod
		}
		pctStr = fmt.Sprintf("%02d", mod)
	}
	line := discRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Println(line)
	performReadPara()
}

func summaryPara() {
	WsTotalEd = formatPZZZZZZZ9_99(WsTotalNet)
	countStr := fmt.Sprintf("%03d", WsCount)
	// overflow already handled
	line := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Println(line)
}

// wrappers for PERFORM naming
func performReadPara() { readPara() }
func performProcessPara() { processPara() }
func performSummaryPara() { summaryPara() }

func main() {
	WsEofFlag = "N"
	WsDiscount = decimal.New(0, -2)
	WsNet = decimal.New(0, -2)
	WsTotalNet = decimal.New(0, -2)
	WsCount = 0

	var err error
	discFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer discFile.Close()
	discReader = bufio.NewReader(discFile)

	// MAIN-PARA
	// OPEN INPUT DISC-FILE already done
	performReadPara()
	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for !isInputDone() {
		performProcessPara()
	}
	// CLOSE DISC-FILE deferred
	performSummaryPara()
}
